clamp:
def clamp(value, low, high):
    """Return value limited to the inclusive range [low, high]."""
    return max(low, min(high, value))

last_index:
def last_index(items):
    """Return the index of the final element, or -1 for an empty list."""
    return len(items) - 1 if items else -1

chunk:
def chunk(items, size):
    """Split items into consecutive lists of at most `size` elements."""
    result = []
    for i in range(0, len(items), size):
        result.append(items[i:i+size])
    return result

median:
def median(numbers):
    """Return the median of a non-empty list of numbers (mean of the middle two when even)."""
    sorted_nums = sorted(numbers)
    n = len(sorted_nums)
    if n % 2 == 1:
        return sorted_nums[n // 2]
    else:
        return (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) / 2

truncate:
def truncate(text, limit):
    """Return text unchanged when it fits in `limit` characters, otherwise cut it
    and end with an ellipsis so the result is exactly `limit` characters long."""
    if len(text) <= limit:
        return text
    else:
        return text[:limit-3] + '...'

count_words:
def count_words(text):
    """Return the number of whitespace-separated words; an empty or blank string has none."""
    return len(text.split()) if text.strip() else 0

is_leap:
def is_leap(year):
    """True when the year is a leap year in the Gregorian calendar."""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

percent:
def percent(part, whole):
    """Return part as a percentage of whole, rounded to one decimal; 0.0 when whole is 0."""
    if whole == 0:
        return 0.0
    return round(part / whole * 100, 1)

dedupe:
def dedupe(items):
    """Remove duplicates, keeping the first occurrence and the original order."""
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

pairs:
def pairs(items):
    """Return each element paired with the one after it: [1,2,3] -> [(1,2),(2,3)]."""
    return list(zip(items, items[1:]))

initials:
def initials(full_name):
    """Return the uppercase initials of each word: 'ada lovelace' -> 'AL'."""
    words = full_name.split()
    return ''.join(word[0].upper() for word in words if word)

clip_index:
def clip_index(index, length):
    """Return a valid index into a sequence of `length` items, clipped into range;
    a negative index counts from the end as Python does."""
    if index < 0:
        index = length + index
    return max(0, min(length - 1, index))

parse_duration:
def parse_duration(text):
    """Parse '1h30m' or '45s' into whole seconds. Missing units are zero."""
    total_seconds = 0
    i = 0
    current_num = ''
    while i < len(text):
        if text[i].isdigit():
            current_num += text[i]
        elif text[i] == 'h':
            if current_num:
                total_seconds += int(current_num) * 3600
            current_num = ''
        elif text[i] == 'm':
            if current_num:
                total_seconds += int(current_num) * 60
            current_num = ''
        elif text[i] == 's':
            if current_num:
                total_seconds += int(current_num)
            current_num = ''
        i += 1
    return total_seconds

balanced:
def balanced(text):
    """True when every round bracket in the text is opened before it is closed and all are closed."""
    count = 0
    for char in text:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

average_or_zero:
def average_or_zero(numbers):
    """Return the mean, or 0 when the list is empty."""
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)
